from django.db import migrations, models


def costo_de_lo_ya_vendido(apps, schema_editor):
    """
    Las ventas cobradas antes de que existiera la foto del costo se completan
    con el costo que el producto tiene hoy: es el mejor dato disponible, y
    así, desde ahora, tampoco cambian si el costo se actualiza.
    """
    ItemPedido = apps.get_model('ventas', 'ItemPedido')
    for item in (ItemPedido.objects
                 .filter(pedido__estado='pagado', costo_unitario__isnull=True,
                         variante__producto__precio_costo__gt=0)
                 .select_related('variante__producto').iterator()):
        item.costo_unitario = item.variante.producto.precio_costo
        item.save(update_fields=['costo_unitario'])


